import { Request, Response } from 'express';
import { CreateTaskUseCase } from '../application/CreateTaskUseCase';
import { AssignTaskUseCase } from '../application/AssignTaskUseCase';
import { MarkTaskDoneUseCase } from '../application/MarkTaskDoneUseCase';
import { ListTasksUseCase } from '../application/ListTasksUseCase';
import { isValidTaskStatus } from '../domain/TaskStatus';

export class TaskController {
  constructor(
    private createTaskUseCase: CreateTaskUseCase,
    private assignTaskUseCase: AssignTaskUseCase,
    private markTaskDoneUseCase: MarkTaskDoneUseCase,
    private listTasksUseCase: ListTasksUseCase,
  ) {}

  createTask = (req: Request, res: Response): void => {
    try {
      const { projectId, title, description, dueDate } = req.body;

      if (!projectId || typeof projectId !== 'string') {
        res.status(400).json({ error: 'Project ID is required and must be a string' });
        return;
      }

      if (!title || typeof title !== 'string') {
        res.status(400).json({ error: 'Title is required and must be a string' });
        return;
      }

      if (!description || typeof description !== 'string') {
        res.status(400).json({ error: 'Description is required and must be a string' });
        return;
      }

      const normalizedDueDate = dueDate === null ? null : dueDate;

      const response = this.createTaskUseCase.execute({
        projectId,
        title,
        description,
        dueDate: normalizedDueDate,
      });
      res.status(201).json(response);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Internal server error';
      const statusCode = message === 'Project not found' ? 404 : 500;
      res.status(statusCode).json({ error: message });
    }
  };

  assignTask = (req: Request, res: Response): void => {
    try {
      const { taskId, userId } = req.body;

      if (!taskId || typeof taskId !== 'string') {
        res.status(400).json({ error: 'Task ID is required and must be a string' });
        return;
      }

      if (!userId || typeof userId !== 'string') {
        res.status(400).json({ error: 'User ID is required and must be a string' });
        return;
      }

      const response = this.assignTaskUseCase.execute({ taskId, userId });
      res.status(200).json(response);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Internal server error';
      const statusCode = message === 'Task not found' || message === 'User not found' ? 404 : 500;
      res.status(statusCode).json({ error: message });
    }
  };

  markTaskDone = (req: Request, res: Response): void => {
    try {
      const { taskId } = req.body;

      if (!taskId || typeof taskId !== 'string') {
        res.status(400).json({ error: 'Task ID is required and must be a string' });
        return;
      }

      const response = this.markTaskDoneUseCase.execute({ taskId });
      res.status(200).json(response);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Internal server error';
      const statusCode = message === 'Task not found' ? 404 : 400;
      res.status(statusCode).json({ error: message });
    }
  };

  listTasks = (req: Request, res: Response): void => {
    try {
      const projectId = req.query.projectId;
      const status = req.query.status;
      const assigneeId = req.query.assigneeId;

      if (!projectId || typeof projectId !== 'string') {
        res.status(400).json({ error: 'Project ID is required as a query parameter' });
        return;
      }

      let normalizedStatus = undefined;
      if (status) {
        if (!isValidTaskStatus(status)) {
          res.status(400).json({ error: 'Invalid status value' });
          return;
        }
        normalizedStatus = status;
      }

      const normalizedAssigneeId = assigneeId && typeof assigneeId === 'string' ? assigneeId : undefined;

      const response = this.listTasksUseCase.execute({
        projectId,
        status: normalizedStatus,
        assigneeId: normalizedAssigneeId,
      });
      res.status(200).json(response);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Internal server error';
      const statusCode = message === 'Project not found' ? 404 : 500;
      res.status(statusCode).json({ error: message });
    }
  };
}

